/** కెర్నల్_మూల్యం 안의 연결형 బైట్_మూల్యం ధార_మూల్యం. Ethernet/TCP 패킷 스택이 아닌 루프백 socket పొర_మూల్యం. */
public final class ధార_నెట్_వర్క్ {
    static int[] స్థితి_మూల్యం = new int[16], పోర్టు_మూల్యం = new int[16], 짝 = new int[16], పియర్_పోర్టు = new int[16], వేచియుండు_మూల్యం = new int[16], 묶임 = new int[16];
    static int[] ముందు_మూల్యం = new int[16], 수 = new int[16], డేటా = new int[16 * 1024];
    static int తదుపరి_అంశం = 50000;
    static int సరిచూడు(int 열린파일번호) { return 열린파일번호 >= 40 && 열린파일번호 < 56 && స్థితి_మూల్యం[열린파일번호 - 40] != 0 ? 열린파일번호 - 40 : -1; }
    static boolean 사용중(int పోర్ట్_సంఖ్య) { for (int లూప్_సూచీ = 0; లూప్_సూచీ < 16; లూప్_సూచీ++) if (స్థితి_మూల్యం[లూప్_సూచీ] != 0 && 묶임[లూప్_సూచీ] != 0 && పోర్టు_మూల్యం[లూప్_సూచీ] == పోర్ట్_సంఖ్య) return true; return false; }
    public static int క్రియేట్_ప్రవేశం() {
        for (int లూప్_సూచీ = 0; లూప్_సూచీ < 16; లూప్_సూచీ++) if (స్థితి_మూల్యం[లూప్_సూచీ] == 0) { స్థితి_మూల్యం[లూప్_సూచీ] = 1; పియర్_పోర్టు[లూప్_సూచీ] = పోర్టు_మూల్యం[లూప్_సూచీ] = ముందు_మూల్యం[లూప్_సూచీ] = 수[లూప్_సూచీ] = వేచియుండు_మూల్యం[లూప్_సూచీ] = 묶임[లూప్_సూచీ] = 0; 짝[లూప్_సూచీ] = -1; return లూప్_సూచీ + 40; }
        return -24;
    }
    public static int 묶기(int 열린파일번호, int 통신주소, int పోర్ట్_సంఖ్య) {
        int లూప్_సూచీ = సరిచూడు(열린파일번호); if (లూప్_సూచీ < 0) return -9;
        if (통신주소 != 0 && 통신주소 != 0x7f000001) return -99;
        if (స్థితి_మూల్యం[లూప్_సూచీ] != 1 || పోర్ట్_సంఖ్య < 0 || పోర్ట్_సంఖ్య > 65535) return -22;
        if (పోర్ట్_సంఖ్య == 0) { do { పోర్ట్_సంఖ్య = తదుపరి_అంశం++; if (తదుపరి_అంశం > 65535) తదుపరి_అంశం = 50000; } while (사용중(పోర్ట్_సంఖ్య)); }
        if (사용중(పోర్ట్_సంఖ్య)) return -98; పోర్టు_మూల్యం[లూప్_సూచీ] = పోర్ట్_సంఖ్య; 묶임[లూప్_సూచీ] = 1; స్థితి_మూల్యం[లూప్_సూచీ] = 2; return 0;
    }
    public static int 듣기(int 열린파일번호, int 연결대기한도) { int లూప్_సూచీ = సరిచూడు(열린파일번호); if (లూప్_సూచీ < 0) return -9; if (స్థితి_మూల్యం[లూప్_సూచీ] != 2 || 연결대기한도 < 1) return -22; స్థితి_మూల్యం[లూప్_సూచీ] = 3; return 0; }
    public static int కనెక్టుచేయి(int 열린파일번호, int 통신주소, int పోర్ట్_సంఖ్య) {
        int లూప్_సూచీ = సరిచూడు(열린파일번호); if (లూప్_సూచీ < 0) return -9; if (통신주소 != 0x7f000001) return -101;
        if (పోర్ట్_సంఖ్య < 1 || పోర్ట్_సంఖ్య > 65535 || స్థితి_మూల్యం[లూప్_సూచీ] > 2) return -22;
        int 수신쪽 = -1; for (int ఇన్నర్_జాయిన్_స్థాయి = 0; ఇన్నర్_జాయిన్_స్థాయి < 16; ఇన్నర్_జాయిన్_స్థాయి++) if (స్థితి_మూల్యం[ఇన్నర్_జాయిన్_స్థాయి] == 3 && పోర్టు_మూల్యం[ఇన్నర్_జాయిన్_స్థాయి] == పోర్ట్_సంఖ్య) 수신쪽 = ఇన్నర్_జాయిన్_స్థాయి;
        if (수신쪽 < 0) return -111;
        int 대기여부 = 0; for (int ఇన్నర్_జాయిన్_స్థాయి = 0; ఇన్నర్_జాయిన్_స్థాయి < 16; ఇన్నర్_జాయిన్_స్థాయి++) if (వేచియుండు_మూల్యం[ఇన్నర్_జాయిన్_స్థాయి] == 수신쪽 + 1) 대기여부++;
        if (대기여부 >= 4) return -11;
        if (స్థితి_మూల్యం[లూప్_సూచీ] == 1) { int 처리값 = 묶기(열린파일번호, 0x7f000001, 0); if (처리값 < 0) return 처리값; }
        int 다른번호 = క్రియేట్_ప్రవేశం(); if (다른번호 < 0) return 다른번호; 다른번호 -= 40;
        స్థితి_మూల్యం[లూప్_సూచీ] = స్థితి_మూల్యం[다른번호] = 4; 짝[లూప్_సూచీ] = 다른번호; 짝[다른번호] = లూప్_సూచీ; పోర్టు_మూల్యం[다른번호] = పోర్ట్_సంఖ్య; పియర్_పోర్టు[లూప్_సూచీ] = పోర్ట్_సంఖ్య; పియర్_పోర్టు[다른번호] = పోర్టు_మూల్యం[లూప్_సూచీ]; వేచియుండు_మూల్యం[다른번호] = 수신쪽 + 1; return 0;
    }
    public static int ఆమోదించు_కనెక్షన్(int 열린파일번호) { int లూప్_సూచీ = సరిచూడు(열린파일번호); if (లూప్_సూచీ < 0) return -9; if (స్థితి_మూల్యం[లూప్_సూచీ] != 3) return -22; for (int ఇన్నర్_జాయిన్_స్థాయి = 0; ఇన్నర్_జాయిన్_స్థాయి < 16; ఇన్నర్_జాయిన్_స్థాయి++) if (స్థితి_మూల్యం[ఇన్నర్_జాయిన్_స్థాయి] != 0 && వేచియుండు_మూల్యం[ఇన్నర్_జాయిన్_స్థాయి] == లూప్_సూచీ + 1) { వేచియుండు_మూల్యం[ఇన్నర్_జాయిన్_స్థాయి] = 0; return ఇన్నర్_జాయిన్_స్థాయి + 40; } return -11; }
    public static int వ్రాయుము(int 열린파일번호, int 항목수) {
        int లూప్_సూచీ = సరిచూడు(열린파일번호); if (లూప్_సూచీ < 0) return -9; if (స్థితి_మూల్యం[లూప్_సూచీ] != 4) return -107;
        if (항목수 < 0 || 항목수 > 512) return -22; if (항목수 == 0) return 0;
        int ఇన్నర్_జాయిన్_స్థాయి = 짝[లూప్_సూచీ]; if (ఇన్నర్_జాయిన్_స్థాయి < 0) return -32; int 총수 = 1024 - 수[ఇన్నర్_జాయిన్_స్థాయి]; if (총수 == 0) return -11; if (총수 > 항목수) 총수 = 항목수;
        for (int పోలిక_స్థాయి = 0; పోలిక_స్థాయి < 총수; పోలిక_స్థాయి++) డేటా[ఇన్నర్_జాయిన్_స్థాయి * 1024 + (ముందు_మూల్యం[ఇన్నర్_జాయిన్_స్థాయి] + 수[ఇన్నర్_జాయిన్_స్థాయి] + పోలిక_స్థాయి) % 1024] = 되돌림망.ఫార్వార్డ్_మూల్యం[పోలిక_స్థాయి]; 수[ఇన్నర్_జాయిన్_స్థాయి] += 총수; return 총수;
    }
    public static int చదువు(int 열린파일번호, int 항목수) {
        int లూప్_సూచీ = సరిచూడు(열린파일번호); if (లూప్_సూచీ < 0) return -9; if (స్థితి_మూల్యం[లూప్_సూచీ] != 4) return -107; if (항목수 < 0 || 항목수 > 512) return -22;
        if (항목수 == 0) return 0; if (수[లూప్_సూచీ] == 0) return 짝[లూప్_సూచీ] < 0 ? 0 : -11; if (항목수 > 수[లూప్_సూచీ]) 항목수 = 수[లూప్_సూచీ];
        for (int పోలిక_స్థాయి = 0; పోలిక_స్థాయి < 항목수; పోలిక_స్థాయి++) 되돌림망.ఫార్వార్డ్_మూల్యం[పోలిక_స్థాయి] = డేటా[లూప్_సూచీ * 1024 + (ముందు_మూల్యం[లూప్_సూచీ] + పోలిక_స్థాయి) % 1024]; ముందు_మూల్యం[లూప్_సూచీ] = (ముందు_మూల్యం[లూప్_సూచీ] + 항목수) % 1024; 수[లూప్_సూచీ] -= 항목수; return 항목수;
    }
    public static int 창구읽기(int 열린파일번호) { int లూప్_సూచీ = సరిచూడు(열린파일번호); return లూప్_సూచీ < 0 ? -9 : పోర్టు_మూల్యం[లూప్_సూచీ]; }
    public static int 상대창구읽기(int 열린파일번호) { int లూప్_సూచీ = సరిచూడు(열린파일번호); return లూప్_సూచీ < 0 ? -9 : పియర్_పోర్టు[లూప్_సూచీ]; }
    public static int మూసివేయి(int 열린파일번호) {
        int లూప్_సూచీ = సరిచూడు(열린파일번호); if (లూప్_సూచీ < 0) return -9;
        if (స్థితి_మూల్యం[లూప్_సూచీ] == 3) for (int ఇన్నర్_జాయిన్_స్థాయి = 0; ఇన్నర్_జాయిన్_స్థాయి < 16; ఇన్నర్_జాయిన్_స్థాయి++) if (వేచియుండు_మూల్యం[ఇన్నర్_జాయిన్_స్థాయి] == లూప్_సూచీ + 1) { if (짝[ఇన్నర్_జాయిన్_స్థాయి] >= 0) 짝[짝[ఇన్నర్_జాయిన్_స్థాయి]] = -1; స్థితి_మూల్యం[ఇన్నర్_జాయిన్_స్థాయి] = వేచియుండు_మూల్యం[ఇన్నర్_జాయిన్_స్థాయి] = 묶임[ఇన్నర్_జాయిన్_స్థాయి] = 0; }
        if (짝[లూప్_సూచీ] >= 0) 짝[짝[లూప్_సూచీ]] = -1; స్థితి_మూల్యం[లూప్_సూచీ] = 묶임[లూప్_సూచీ] = 수[లూప్_సూచీ] = వేచియుండు_మూల్యం[లూప్_సూచీ] = 0; return 0;
    }
}
